    -- or prerequisite completion can make it usable without rebuilding it.
    if self.CanStartRoute and not self:CanStartRoute(currentRouteKey) then
        self._blockedRouteKey = currentRouteKey
        return nil, 0, '', ''
    end
    self._blockedRouteKey = nil
